js:(async () => { const H = { 'Content-Type': 'application/json', Authorization: 'Bearer ' + localStorage.getItem('erp_token') }; const g = async (u) => (await fetch(u, { headers: H })).json(); const today = new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 10); const sum = async (k) => (await g('/api/ledger/partner-balances?asOf=' + today + '&unbilledFrom=' + new Date(new Date(today).setFullYear(new Date(today).getFullYear() - 1)).toISOString().slice(0, 10))).reduce((a, r) => a + r[k], 0); const base = { ar: await sum('unbilledReceivable'), ap: await sum('unbilledPayable') };
 let p = (await g('/api/partners')).find((x) => x.code === 'QAB7P'); if (!p) p = await (await fetch('/api/partners', { method: 'POST', headers: H, body: JSON.stringify({ code: 'QAB7P', name: 'QA재고1-미청구', type: 'BOTH' }) })).json();
 let it = (await g('/api/items')).find((x) => x.code === 'QAB7-Z'); if (!it) it = await (await fetch('/api/items', { method: 'POST', headers: H, body: JSON.stringify({ code: 'QAB7-Z', name: 'QA미청구-품목', category: 'MERCHANDISE', unitPrice: 0, safetyStock: 0 }) })).json();
 const wh = (await g('/api/warehouses')).find((x) => x.code === 'WH-01');
 const r = await (await fetch('/api/purchases', { method: 'POST', headers: H, body: JSON.stringify({ partnerId: p.id, warehouseId: wh.id, purchaseDate: today, taxable: true, remark: 'QA재고1 미청구 재고', lines: [{ itemId: it.id, quantity: 10, unitPrice: 100 }] }) })).json();
 sessionStorage.setItem('b7', JSON.stringify({ purchaseId: r.id, partnerId: p.id, itemId: it.id, base })); return r.id })()
